# Minimal H5 dataset for the fusion backbone (olmoearth delivery deferred).
#
# For the shape-verification stage, olmoearth context is generated by a stub
# (see custom_models.fusion_backbone.StubOlmoEarth).  The real olmoearth
# pipeline (custom segmentor + preprocessor that threads olmoearth from the
# batch to backbone.forward) is deferred to a follow-up change.
#
# This module provides:
#   LoadFusionH5  – a transform that reads the HR image from a fake H5.
#   FusionH5Dataset – a BaseSegDataset subclass that can consume a split file.

import numpy as np
import h5py
from mmseg.registry import TRANSFORMS, DATASETS
from mmseg.datasets import BaseSegDataset


@TRANSFORMS.register_module()
class LoadFusionH5:
    """Read the HR image (key 'HR') from an H5 file and put it on ``results['img']``.

    The image is returned as a float32 numpy array (H, W, C).  Normalization
    is deferred — a dummy pass-through normalize can be added later.
    """

    def __init__(self, img_size=480, key="HR"):
        self.img_size = img_size
        self.key = key

    def __call__(self, results):
        path = results["img_path"]
        with h5py.File(path, "r") as f:
            img = f[self.key][()]
        img = img.astype(np.float32)
        results["img"] = img
        results["img_shape"] = img.shape
        results["ori_shape"] = img.shape
        # dummy mask for shape verification (all ones)
        results["gt_seg_map"] = np.ones(
            (self.img_size, self.img_size), dtype=np.int64
        )
        results["seg_fields"] = ["gt_seg_map"]
        return results


@DATASETS.register_module()
class FusionH5Dataset(BaseSegDataset):
    """Minimal dataset for the fusion backbone.

    Expects a split file (one H5 path per line) under ``data_root``.
    """

    METAINFO = dict(classes=["background", "foreground"], palette=[[0, 0, 0], [34, 139, 34]])

    def __init__(self, data_root, split="train", **kwargs):
        super().__init__(data_root=data_root, **kwargs)
        self.split = split

    def load_data_list(self):
        split_path = f"{self.data_root}/{self.split}.txt"
        data_list = []
        with open(split_path, "r") as f:
            for line in f:
                line = line.strip()
                if line:
                    data_list.append({"img_path": f"{self.data_root}/{line}"})
        return data_list
